INSERT INTO `wordbooks` VALUES (1, 'cet4', '大学英语四级 CET-4 核心高频词', '覆盖四级考试高频核心词，按词频与常见度编排，适合每日默写刷词。', 'CET-4', 147, '2026-10-19 21:14:46', 'active');
INSERT INTO `wordbooks` VALUES (2, 'cet6', '大学英语六级 CET-6 进阶高频词', '六级高频进阶词汇，侧重学术与书面语场景，适合四级基础巩固后进阶。', 'CET-6', 57, '2026-10-19 21:14:46', 'active');
INSERT INTO `wordbooks` VALUES (3, 'gaokao', '高中核心基础词', '高中阶段高频基础词，重在拼写准确与基本用法，适合打牢地基。', '高中', 51, '2026-10-19 21:14:46', 'active');
INSERT INTO `wordbooks` VALUES (4, 'kaoyan', '考研核心词汇', '研究生入学考试高频核心词，偏学术书面语，重在精确释义与搭配。', '考研', 58, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (1, 1, 'abandon', '/əˈbændən/', 'v. 放弃，遗弃', 'They had to abandon the plan for lack of funds.', '由于缺乏资金，他们不得不放弃这个计划。', 0, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (2, 1, 'ability', '/əˈbɪləti/', 'n. 能力，才能', 'She has the ability to solve complex problems quickly.', '她有能力迅速解决复杂问题。', 1, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (3, 1, 'abnormal', '/æbˈnɔːml/', 'adj. 反常的，异常的', 'The abnormal weather disrupted the harvest.', '反常的天气打乱了收成。', 2, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (4, 1, 'abolish', '/əˈbɒlɪʃ/', 'v. 废除，取消', 'The government decided to abolish the outdated rule.', '政府决定废除这项过时的规定。', 3, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (5, 1, 'absorb', '/əbˈzɔːb/', 'v. 吸收；吸引', 'Plants absorb water and minerals from the soil.', '植物从土壤中吸收水分和矿物质。', 4, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (6, 1, 'abstract', '/ˈæbstrækt/', 'adj. 抽象的 n. 摘要', 'He found the theory too abstract to apply in practice.', '他觉得这个理论太抽象，难以付诸实践。', 5, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (7, 1, 'abundant', '/əˈbʌndənt/', 'adj. 丰富的，充裕的', 'The region is abundant in natural resources.', '该地区自然资源丰富。', 6, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (8, 1, 'abuse', '/əˈbjuːs/', 'n. 滥用，弊端 v. 滥用；虐待', 'The new law aims to prevent the abuse of power.', '新法律旨在防止权力滥用。', 7, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (9, 1, 'accelerate', '/əkˈseləreɪt/', 'v. 加速，促进', 'The company plans to accelerate its expansion overseas.', '公司计划加速海外扩张。', 8, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (10, 1, 'accident', '/ˈæksɪdənt/', 'n. 事故，意外', 'He was injured in a traffic accident last winter.', '去年冬天他在一场交通事故中受伤。', 9, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (11, 1, 'accommodate', '/əˈkɒmədeɪt/', 'v. 容纳；提供住宿', 'The new hall can accommodate up to eight hundred guests.', '新大厅最多可容纳八百名来宾。', 10, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (12, 1, 'accompany', '/əˈkʌmpəni/', 'v. 陪伴，伴随', 'Would you like me to accompany you to the station?', '要我陪你去车站吗？', 11, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (13, 1, 'accomplish', '/əˈkʌmplɪʃ/', 'v. 完成，实现', 'We accomplished the task ahead of schedule.', '我们提前完成了任务。', 12, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (14, 1, 'account', '/əˈkaʊnt/', 'n. 账户；描述 v. 解释', 'He gave a full account of what happened that night.', '他完整讲述了那天夜里发生的事情。', 13, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (15, 1, 'accumulate', '/əˈkjuːmjəleɪt/', 'v. 积累，积聚', 'It takes years to accumulate enough experience.', '积累足够的经验需要多年时间。', 14, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (16, 1, 'accurate', '/ˈækjərət/', 'adj. 精确的，准确的', 'The report gives an accurate picture of the market.', '这份报告准确地反映了市场状况。', 15, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (17, 1, 'accuse', '/əˈkjuːz/', 'v. 指控，指责', 'They accused him of stealing the documents.', '他们指控他窃取了文件。', 16, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (18, 1, 'achieve', '/əˈtʃiːv/', 'v. 实现，达到', 'She achieved her goal after years of hard work.', '经过多年的努力，她实现了自己的目标。', 17, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (19, 1, 'acknowledge', '/əkˈnɒlɪdʒ/', 'v. 承认；确认收到', 'He refused to acknowledge his mistake.', '他拒绝承认自己的错误。', 18, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (20, 1, 'acquire', '/əˈkwaɪə(r)/', 'v. 获得，取得', 'Children acquire language very quickly.', '儿童学习语言非常快。', 19, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (21, 1, 'adapt', '/əˈdæpt/', 'v. 适应；改编', 'You will adapt to the new environment soon.', '你很快就会适应新环境。', 20, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (22, 1, 'adequate', '/ˈædɪkwət/', 'adj. 足够的，适当的', 'Make sure you get adequate sleep before the exam.', '确保考试前有足够的睡眠。', 21, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (23, 1, 'adjust', '/əˈdʒʌst/', 'v. 调整，调节', 'It took me a week to adjust to the new schedule.', '我花了一周才适应新的作息安排。', 22, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (24, 1, 'administration', '/ədˌmɪnɪˈstreɪʃn/', 'n. 管理；行政部门', 'The administration approved the new policy.', '行政部门批准了这项新政策。', 23, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (25, 1, 'admire', '/ədˈmaɪə(r)/', 'v. 钦佩，赞赏', 'I really admire her courage and patience.', '我真的很佩服她的勇气和耐心。', 24, '2026-10-19 21:14:46', 'active');
