INSERT INTO `words` VALUES (27, 1, 'adopt', '/əˈdɒpt/', 'v. 采用；收养', 'Many firms have adopted this new method.', '许多公司已经采用这种新方法。', 26, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (28, 1, 'advance', '/ədˈvɑːns/', 'v. 前进，进展 n. 进步', 'Technology continues to advance at a rapid pace.', '技术以极快的速度发展。', 27, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (29, 1, 'advantage', '/ədˈvɑːntɪdʒ/', 'n. 优势，有利条件', 'Speaking two languages is a great advantage.', '会说两种语言是一个很大的优势。', 28, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (30, 1, 'advertise', '/ˈædvətaɪz/', 'v. 做广告，宣传', 'The company advertises its products on television.', '这家公司在电视上为其产品做广告。', 29, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (31, 1, 'advocate', '/ˈædvəkeɪt/', 'v. 提倡，主张 n. 倡导者', 'She advocates reading for at least thirty minutes a day.', '她提倡每天至少阅读三十分钟。', 30, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (32, 1, 'affect', '/əˈfekt/', 'v. 影响', 'The decision will affect thousands of families.', '这个决定将影响成千上万个家庭。', 31, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (33, 1, 'afford', '/əˈfɔːd/', 'v. 负担得起', 'We cannot afford to waste any more time.', '我们浪费不起更多时间了。', 32, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (34, 1, 'aggressive', '/əˈɡresɪv/', 'adj. 侵略的；有进取心的', 'The dog became aggressive when strangers came near.', '陌生人靠近时，那条狗变得很有攻击性。', 33, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (35, 1, 'allocate', '/ˈæləkeɪt/', 'v. 分配，分派', 'We need to allocate more budget to marketing.', '我们需要为市场部分配更多预算。', 34, '2026-10-19 21:14:46', 'active');
