INSERT INTO `words` VALUES (37, 1, 'alternative', '/ɔːlˈtɜːnətɪv/', 'adj. 备选的 n. 替代方案', 'We should look for an alternative solution.', '我们应该寻找替代方案。', 36, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (38, 1, 'ambiguous', '/æmˈbɪɡjuəs/', 'adj. 模糊的，有歧义的', 'The wording of the contract is ambiguous.', '合同的措辞含糊不清。', 37, '2026-10-19 21:14:46', 'active');
