INSERT INTO `words` VALUES (40, 1, 'amend', '/əˈmend/', 'v. 修正，修改', 'The committee agreed to amend the original draft.', '委员会同意修改原草案。', 39, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (41, 1, 'analyse', '/ˈænəlaɪz/', 'v. 分析，解析', 'Scientists analysed the data collected over ten years.', '科学家分析了十年间收集的数据。', 40, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (42, 1, 'annual', '/ˈænjuəl/', 'adj. 每年的 n. 年刊', 'The annual report will be released next month.', '年报将于下月发布。', 41, '2026-10-19 21:14:46', 'active');
