INSERT INTO `words` VALUES (45, 1, 'apparent', '/əˈpærənt/', 'adj. 明显的；表面上的', 'It was apparent that he had not read the email.', '很明显他没有读那封邮件。', 44, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (46, 1, 'appeal', '/əˈpiːl/', 'n./v. 呼吁；上诉；吸引', 'The idea appealed to young customers.', '这个想法吸引了年轻顾客。', 45, '2026-10-19 21:14:46', 'active');
