INSERT INTO `words` VALUES (48, 1, 'appliance', '/əˈplaɪəns/', 'n. 器具，电器', 'The kitchen is equipped with modern appliances.', '厨房配备了现代化电器。', 47, '2026-10-19 21:14:46', 'active');
