INSERT INTO `words` VALUES (50, 1, 'appoint', '/əˈpɔɪnt/', 'v. 任命，约定', 'They appointed him as the new manager.', '他们任命他为新任经理。', 49, '2026-10-19 21:14:46', 'active');
