INSERT INTO `words` VALUES (57, 1, 'architecture', '/ˈɑːkɪtektʃə(r)/', 'n. 建筑学，建筑风格', 'The city is famous for its modern architecture.', '这座城市以其现代建筑闻名。', 56, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (58, 1, 'arise', '/əˈraɪz/', 'v. 出现，产生', 'Problems may arise when the two systems meet.', '两套系统对接时可能会出现问题。', 57, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (59, 1, 'arrange', '/əˈreɪndʒ/', 'v. 安排，筹备', 'Let me arrange a meeting for next Tuesday.', '让我安排下周二开个会。', 58, '2026-10-19 21:14:46', 'active');
