INSERT INTO `words` VALUES (73, 1, 'audience', '/ˈɔːdiəns/', 'n. 听众，观众', 'The audience applauded for several minutes.', '观众鼓掌持续了好几分钟。', 72, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (74, 1, 'authority', '/ɔːˈθɒrəti/', 'n. 权威；当局', 'The local authority closed the old bridge.', '当地主管部门关闭了那座旧桥。', 73, '2026-10-19 21:14:46', 'active');
