INSERT INTO `words` VALUES (76, 1, 'available', '/əˈveɪləbl/', 'adj. 可获得的；有空的', 'The manager is available on Friday afternoon.', '经理周五下午有空。', 75, '2026-10-19 21:14:46', 'active');
