INSERT INTO `words` VALUES (79, 1, 'avoid', '/əˈvɔɪd/', 'v. 避免，回避', 'Try to avoid making the same mistake twice.', '尽量避免重复犯同样的错误。', 78, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (80, 1, 'aware', '/əˈweə(r)/', 'adj. 意识到的', 'Many people are unaware of the risks involved.', '许多人没有意识到其中的风险。', 79, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (81, 1, 'awful', '/ˈɔːfl/', 'adj. 糟糕的，极坏的', 'The weather was awful during our whole trip.', '我们整个旅途的天气都很糟糕。', 80, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (82, 1, 'bachelor', '/ˈbætʃələ(r)/', 'n. 学士；单身汉', 'She graduated with a bachelor of arts degree.', '她取得了文学学士学位毕业。', 81, '2026-10-19 21:14:46', 'active');
