INSERT INTO `words` VALUES (84, 1, 'balance', '/ˈbæləns/', 'n./v. 平衡', 'It is hard to balance work and family life.', '平衡工作与家庭生活很难。', 83, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (85, 1, 'ban', '/bæn/', 'v./n. 禁止，取缔', 'The city banned smoking in public places.', '该市禁止在公共场所吸烟。', 84, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (86, 1, 'barrier', '/ˈbæriə(r)/', 'n. 障碍，屏障', 'Language can be a barrier to communication.', '语言可能成为沟通的障碍。', 85, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (87, 1, 'behalf', '/bɪˈhɑːf/', 'n. 代表，利益', 'The lawyer spoke on behalf of the whole team.', '律师代表整个团队发了言。', 86, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (88, 1, 'behave', '/bɪˈheɪv/', 'v. 表现，举止', 'The children behaved remarkably well today.', '孩子们今天表现得非常好。', 87, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (89, 1, 'belief', '/bɪˈliːf/', 'n. 信念，相信', 'She never lost her belief in justice.', '她从未失去对正义的信念。', 88, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (90, 1, 'beloved', '/bɪˈlʌvd/', 'adj. 心爱的', 'He returned to his beloved hometown after thirty years.', '三十年后他回到了自己深爱的故乡。', 89, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (91, 1, 'benefit', '/ˈbenɪfɪt/', 'n. 益处 v. 有益于', 'Regular exercise benefits both body and mind.', '经常锻炼有益于身心。', 90, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (92, 1, 'blame', '/bleɪm/', 'v./n. 责备，归咎', 'Do not blame others for your own mistakes.', '不要把自己的错误归咎于他人。', 91, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (93, 1, 'blast', '/blɑːst/', 'n./v. 爆炸，冲击', 'A sudden blast of cold air entered the room.', '一股寒风突然吹进房间。', 92, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (94, 1, 'blend', '/blend/', 'v./n. 混合，融合', 'Blend the flour and butter until smooth.', '把面粉和黄油搅拌至顺滑。', 93, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (95, 1, 'bond', '/bɒnd/', 'n. 纽带，债券', 'Shared struggles created a strong bond between them.', '共同的奋斗在他们之间建立了牢固的纽带。', 94, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (96, 1, 'boost', '/buːst/', 'v./n. 促进，提升', 'The new campaign boosted sales by thirty percent.', '新活动使销量提升了百分之三十。', 95, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (97, 1, 'borrow', '/ˈbɒrəʊ/', 'v. 借入，借用', 'May I borrow your dictionary for a moment?', '我可以借你的词典用一下吗？', 96, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (98, 1, 'bounce', '/baʊns/', 'v./n. 弹起，反弹', 'The ball bounced off the wall and rolled away.', '球撞到墙上弹开，滚远了。', 97, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (99, 1, 'brain', '/breɪn/', 'n. 大脑，头脑', 'The human brain contains billions of neurons.', '人脑包含数十亿个神经元。', 98, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (100, 1, 'brief', '/briːf/', 'adj. 简短的 n. 摘要', 'He gave a brief summary of the meeting.', '他对会议做了简短总结。', 99, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (101, 1, 'brilliant', '/ˈbrɪliənt/', 'adj. 杰出的；灿烂的', 'She came up with a brilliant idea.', '她想出了一个绝妙的主意。', 100, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (102, 1, 'budget', '/ˈbʌdʒɪt/', 'n. 预算', 'The project exceeded its original budget.', '该项目超出了原预算。', 101, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (103, 1, 'bulk', '/bʌlk/', 'n. 大量，大部分', 'The bulk of the work was already finished.', '大部分工作已经完成。', 102, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (104, 1, 'bump', '/bʌmp/', 'v./n. 碰撞，撞击', 'Be careful not to bump your head on the shelf.', '小心别把头撞到架子上。', 103, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (105, 1, 'burst', '/bɜːst/', 'v./n. 爆发，突然发作', 'The crowd burst into laughter.', '人群突然爆发出笑声。', 104, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (106, 1, 'calculate', '/ˈkælkjuleɪt/', 'v. 计算，估算', 'Can you calculate the total cost?', '你能算出总花费吗？', 105, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (107, 1, 'campaign', '/kæmˈpeɪn/', 'n. 运动，战役', 'The campaign to plant trees started last spring.', '植树活动去年春天开始了。', 106, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (108, 1, 'capable', '/ˈkeɪpəbl/', 'adj. 有能力的', 'She is capable of handling the task alone.', '她有能力独立处理这项任务。', 107, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (109, 1, 'capacity', '/kəˈpæsəti/', 'n. 容量；能力', 'The stadium has a capacity of sixty thousand.', '这座体育场可容纳六万人。', 108, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (110, 1, 'capture', '/ˈkæptʃə(r)/', 'v./n. 捕获，夺取', 'The photographer captured the moment perfectly.', '摄影师完美地捕捉了那个瞬间。', 109, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (111, 1, 'career', '/kəˈrɪə(r)/', 'n. 职业，生涯', 'He chose medicine as his lifelong career.', '他把医学作为自己终身的职业。', 110, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (112, 1, 'casual', '/ˈkæʒuəl/', 'adj. 随意的；临时的', 'The meeting had a very casual atmosphere.', '这次会议的气氛非常轻松随意。', 111, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (113, 1, 'category', '/ˈkætəɡəri/', 'n. 类别，种类', 'Books are arranged by category on these shelves.', '书架上的书按类别摆放。', 112, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (114, 1, 'cease', '/siːs/', 'v. 停止，终止', 'The factory ceased production last month.', '这家工厂上月停产了。', 113, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (115, 1, 'ceremony', '/ˈserəməni/', 'n. 典礼，仪式', 'The opening ceremony lasted two hours.', '开幕式持续了两个小时。', 114, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (116, 1, 'challenge', '/ˈtʃælɪndʒ/', 'n./v. 挑战', 'Learning a new language is an exciting challenge.', '学习一门新语言是令人兴奋的挑战。', 115, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (117, 1, 'champion', '/ˈtʃæmpiən/', 'n. 冠军，拥护者', 'She became the national champion at nineteen.', '她十九岁就成了全国冠军。', 116, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (118, 1, 'channel', '/ˈtʃænl/', 'n. 频道；渠道', 'The report was published through official channels.', '该报告是通过官方渠道发布的。', 117, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (119, 1, 'chapter', '/ˈtʃæptə(r)/', 'n. 章，回', 'I finished the first chapter on the train.', '我在火车上读完了第一章。', 118, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (120, 1, 'character', '/ˈkærəktə(r)/', 'n. 性格；角色；字符', 'She has a warm and generous character.', '她性格温暖而慷慨。', 119, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (121, 1, 'charge', '/tʃɑːdʒ/', 'v./n. 收费；指控；充电', 'This hotel charges extra for breakfast.', '这家酒店早餐另外收费。', 120, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (122, 1, 'chase', '/tʃeɪs/', 'v./n. 追赶，追逐', 'The children chased each other across the field.', '孩子们在田野里互相追逐。', 121, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (123, 1, 'cheat', '/tʃiːt/', 'v./n. 欺骗，作弊', 'Anyone caught cheating will be removed from the exam.', '任何被抓到作弊的人都将被清出考场。', 122, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (124, 1, 'chemical', '/ˈkemɪkl/', 'adj. 化学的 n. 化学品', 'The river was polluted by chemical waste.', '这条河被化学废弃物污染了。', 123, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (125, 1, 'cherish', '/ˈtʃerɪʃ/', 'v. 珍爱，怀念', 'She cherishes the letters her grandmother wrote.', '她珍藏着祖母写的那些信。', 124, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (126, 1, 'circumstance', '/ˈsɜːkəmstəns/', 'n. 环境，情况', 'Under no circumstance should you give up.', '在任何情况下你都不该放弃。', 125, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (127, 1, 'citizen', '/ˈsɪtɪzn/', 'n. 市民，公民', 'Every citizen has the right to vote.', '每位公民都有选举权。', 126, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (128, 1, 'civil', '/ˈsɪvl/', 'adj. 公民的；民用的', 'The airport was built for civil aviation.', '这座机场是为民航建造的。', 127, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (129, 1, 'claim', '/kleɪm/', 'v./n. 声称；索要', 'He claims to have seen the accident himself.', '他声称自己亲眼看到了事故。', 128, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (130, 1, 'clarify', '/ˈklærəfaɪ/', 'v. 澄清，阐明', 'Could you clarify what you meant by that?', '你能说明一下那句话的意思吗？', 129, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (131, 1, 'classic', '/ˈklæsɪk/', 'adj. 经典的 n. 名著', 'This novel is a classic of English literature.', '这部小说是英国文学的经典之作。', 130, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (132, 1, 'colleague', '/ˈkɒliːɡ/', 'n. 同事', 'My colleague covered my shift while I was ill.', '我生病时同事替我顶了班。', 131, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (133, 1, 'collect', '/kəˈlekt/', 'v. 收集，聚集', 'He collects stamps from different countries.', '他收集各国邮票。', 132, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (134, 1, 'combine', '/kəmˈbaɪn/', 'v. 结合，联合', 'Combine the two mixtures and stir well.', '把两种混合物拌在一起并充分搅拌。', 133, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (135, 1, 'comment', '/ˈkɒment/', 'n./v. 评论', 'She declined to comment on the rumours.', '她拒绝就传闻发表评论。', 134, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (136, 1, 'commerce', '/ˈkɒmɜːs/', 'n. 商业，贸易', 'Online commerce has grown rapidly in recent years.', '近年来电子商务增长迅速。', 135, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (137, 1, 'commit', '/kəˈmɪt/', 'v. 犯（错误）；承诺；投入', 'It was wrong to commit such a careless mistake.', '犯下这样粗心的错误是不对的。', 136, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (138, 1, 'committee', '/kəˈmɪti/', 'n. 委员会', 'The committee will meet again next week.', '委员会将于下周再次开会。', 137, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (139, 1, 'communicate', '/kəˈmjuːnɪkeɪt/', 'v. 交流，传达', 'It is important to communicate clearly with clients.', '与客户清晰沟通很重要。', 138, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (140, 1, 'community', '/kəˈmjuːnəti/', 'n. 社区，群体', 'The local community raised funds for the school.', '当地社区为学校筹集了资金。', 139, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (141, 1, 'comparable', '/ˈkɒmpərəbl/', 'adj. 可比较的', 'The two products are comparable in quality.', '这两种产品质量相当。', 140, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (142, 1, 'compare', '/kəmˈpeə(r)/', 'v. 比较，对照', 'Compare the two options before you decide.', '在决定之前先比较一下这两个选项。', 141, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (143, 1, 'compensate', '/ˈkɒmpenseɪt/', 'v. 补偿，赔偿', 'Nothing can compensate for the loss of time.', '没有什么能补偿时间的损失。', 142, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (144, 1, 'compete', '/kəmˈpiːt/', 'v. 竞争，比赛', 'Fourteen teams will compete in the final.', '十四支队伍将角逐决赛。', 143, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (145, 1, 'compile', '/kəmˈpaɪl/', 'v. 汇编，编制', 'The team compiled a detailed list of references.', '团队编制了一份详细的参考文献清单。', 144, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (146, 1, 'complex', '/ˈkɒmpleks/', 'adj. 复杂的', 'The human body is an extremely complex machine.', '人体是一台极其复杂的机器。', 145, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (147, 1, 'component', '/kəmˈpəʊnənt/', 'n. 组成部分，部件', 'Cost is a key component of the decision.', '成本是决策的关键因素之一。', 146, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (148, 2, 'abide', '/əˈbaɪd/', 'v. 遵守；容忍', 'All members must abide by the rules of the club.', '所有成员都必须遵守俱乐部的规定。', 0, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (149, 2, 'accrue', '/əˈkruː/', 'v. 累积，逐渐增加', 'Interest will accrue on the savings account.', '储蓄账户会逐渐产生利息。', 1, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (150, 2, 'acquit', '/əˈkwɪt/', 'v. 宣判无罪；表现', 'The jury acquitted him of all charges.', '陪审团宣判他所有指控均不成立。', 2, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (151, 2, 'adamant', '/ˈædəmənt/', 'adj. 坚定不移的', 'She remained adamant that the deadline could not move.', '她坚持截止日期不能更改。', 3, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (152, 2, 'adverse', '/ˈædvɜːs/', 'adj. 不利的，相反的', 'The new policy had an adverse effect on small businesses.', '新政策对小企业产生了不利影响。', 4, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (153, 2, 'admonish', '/əˈmɒnɪʃ/', 'v. 劝告，告诫', 'The teacher admonished him for being late again.', '老师告诫他不要再迟到。', 5, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (154, 2, 'alleviate', '/əˈliːvieɪt/', 'v. 减轻，缓解', 'The medicine alleviated the pain within minutes.', '这种药在几分钟内就缓解了疼痛。', 6, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (155, 2, 'allude', '/əˈluːd/', 'v. 暗指，间接提到', 'He never alluded to the argument in his speech.', '他在演讲中从未提及那次争吵。', 7, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (156, 2, 'ambivalent', '/æmˈbɪvələnt/', 'adj. 矛盾的，犹豫不决的', 'She felt ambivalent about moving abroad.', '对于移居海外，她心情复杂。', 8, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (157, 2, 'ample', '/ˈæmpl/', 'adj. 充足的，丰富的', 'There is ample evidence to support the theory.', '有充分的证据支持这一理论。', 9, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (158, 2, 'amplify', '/ˈæmplɪfaɪ/', 'v. 放大，增强', 'The speaker amplified her voice with a microphone.', '演讲者用麦克风放大了自己的声音。', 10, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (159, 2, 'anonymity', '/ˌænəˈnɪməti/', 'n. 匿名', 'The donor requested complete anonymity.', '捐助者要求完全匿名。', 11, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (160, 2, 'antagonize', '/ænˈtæɡənaɪz/', 'v. 使敌对，激怒', 'His rude remarks only antagonized the audience.', '他粗鲁的言辞只是激怒了观众。', 12, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (161, 2, 'appraise', '/əˈpreɪz/', 'v. 评估，鉴定', 'An expert was asked to appraise the painting.', '一位专家受邀鉴定这幅画。', 13, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (162, 2, 'arcane', '/ɑːˈkeɪn/', 'adj. 神秘的，晦涩的', 'The rules of the game seemed arcane to newcomers.', '这个游戏的规则对新手来说似乎很晦涩。', 14, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (163, 2, 'articulate', '/ɑːˈtɪkjuleɪt/', 'v. 清楚表达 adj. 善于表达的', 'She articulated her proposal with great clarity.', '她非常清晰地阐述了自己的提案。', 15, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (164, 2, 'ascend', '/əˈsend/', 'v. 上升，攀登', 'The trail ascends gradually to the ridge.', '小径缓缓上升通往山脊。', 16, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (165, 2, 'ascribe', '/əˈskraɪb/', 'v. 归因于', 'Critics ascribe the success of the film to its cast.', '评论家把这部电影的成功归功于演员阵容。', 17, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (166, 2, 'aspire', '/əˈspaɪə(r)/', 'v. 渴望，追求', 'Many young writers aspire to publish a novel.', '许多年轻作家渴望出版小说。', 18, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (167, 2, 'assiduous', '/əˈsɪdjuəs/', 'adj. 勤勉的，刻苦的', 'His assiduous preparation paid off in the interview.', '他勤奋的准备在面试中得到了回报。', 19, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (168, 2, 'austere', '/ɒˈstɪə(r)/', 'adj. 朴素的；严厉的', 'The monastery kept an austere daily routine.', '修道院保持着朴素的日常作息。', 20, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (169, 2, 'avarice', '/ˈævərɪs/', 'n. 贪婪', 'His avarice eventually destroyed the partnership.', '他的贪婪最终毁掉了这段合作关系。', 21, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (170, 2, 'avert', '/əˈvɜːt/', 'v. 避免；转移（目光）', 'Quick action averted a serious accident.', '迅速的行动避免了一场严重事故。', 22, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (171, 2, 'avid', '/ˈævɪd/', 'adj. 热衷的，渴望的', 'He is an avid reader of historical biographies.', '他热衷阅读历史传记。', 23, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (172, 2, 'baffle', '/ˈbæfl/', 'v. 使困惑，难倒', 'The puzzle continued to baffle the whole team.', '这个谜题一直难住了整个团队。', 24, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (173, 2, 'barren', '/ˈbærən/', 'adj. 贫瘠的；不结果实的', 'Nothing could grow on the barren hillside.', '贫瘠的山坡上什么也长不出来。', 25, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (174, 2, 'bleak', '/bliːk/', 'adj. 荒凉的；无望的', 'The outlook for the industry looks bleak.', '该行业的前景看起来不容乐观。', 26, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (175, 2, 'blunder', '/ˈblʌndə(r)/', 'n./v. 大错，失足', 'It was a costly blunder that no one noticed.', '那是一个没人注意到的代价惨重的错误。', 27, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (176, 2, 'bolster', '/ˈbəʊlstə(r)/', 'v. 支持，加强', 'The good results bolstered everyone\'s confidence.', '好成绩增强了所有人的信心。', 28, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (177, 2, 'breach', '/briːtʃ/', 'n./v. 违反；突破', 'Leaking the data was a serious breach of trust.', '泄露数据是对信任的严重违背。', 29, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (178, 2, 'brisk', '/brɪsk/', 'adj. 轻快的；兴隆的', 'Business was brisk during the holiday season.', '假期期间生意很兴隆。', 30, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (179, 2, 'brood', '/bruːd/', 'v. 沉思，忧思 n. 一窝', 'Do not brood over mistakes you cannot change.', '不要为无法改变的错误而耿耿于怀。', 31, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (180, 2, 'budge', '/bʌdʒ/', 'v. 稍微移动；改变主意', 'He refused to budge from his decision.', '他拒绝改变自己的决定。', 32, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (181, 2, 'bureaucratic', '/ˌbjʊərəˈkrætɪk/', 'adj. 官僚的，繁文缛节的', 'The application process was slow and bureaucratic.', '申请流程缓慢且充满繁文缛节。', 33, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (182, 2, 'buoyant', '/ˈbɔɪənt/', 'adj. 轻快的；有浮力的', 'Her buoyant mood lifted the whole office.', '她轻快的情绪带动了整个办公室。', 34, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (183, 2, 'buttress', '/ˈbʌtrəs/', 'v. 支持，支撑', 'The lawyer buttressed her argument with statistics.', '律师用统计数据支撑自己的论点。', 35, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (184, 2, 'calamity', '/kəˈlæməti/', 'n. 灾难，祸患', 'The flood was the worst calamity in a century.', '这场洪水是一个世纪以来最严重的灾难。', 36, '2026-10-19 21:14:46', 'active');
