INSERT INTO `words` VALUES (186, 2, 'candour', '/ˈkændə(r)/', 'n. 坦率，真诚', 'She spoke with refreshing candour about her failures.', '她以令人耳目一新的坦率谈及自己的失败。', 38, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (187, 2, 'catastrophe', '/kəˈtæstrəfi/', 'n. 大灾难', 'The oil spill was an environmental catastrophe.', '那次漏油是一场环境大灾难。', 39, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (188, 2, 'caustic', '/ˈkɔːstɪk/', 'adj. 腐蚀性的；尖刻的', 'His caustic wit made him difficult to work with.', '他尖刻的机智让人难以共事。', 40, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (189, 2, 'censure', '/ˈsenʃə(r)/', 'v./n. 责难，指责', 'The committee voted to censure the official.', '委员会投票谴责了这名官员。', 41, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (190, 2, 'chagrin', '/ˈʃæɡrɪn/', 'n. 懊恼，沮丧', 'To her chagrin, the flight was cancelled again.', '令她懊恼的是，航班又取消了。', 42, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (191, 2, 'chronic', '/ˈkrɒnɪk/', 'adj. 慢性的；长期的', 'He has suffered from chronic back pain for years.', '他常年受慢性背痛困扰。', 43, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (192, 2, 'circumspect', '/ˈsɜːkəmspekt/', 'adj. 谨慎的，慎重的', 'Be circumspect when sharing personal details online.', '在网上分享个人信息时要谨慎。', 44, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (193, 2, 'clandestine', '/klænˈdestɪn/', 'adj. 秘密的，暗中的', 'They held a clandestine meeting after midnight.', '他们在午夜后举行了一次秘密会议。', 45, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (194, 2, 'coalesce', '/ˌkəʊəˈles/', 'v. 联合，合并', 'Several small groups coalesced into one movement.', '几个小团体合并成了一场运动。', 46, '2026-10-19 21:14:46', 'active');
