INSERT INTO `words` VALUES (196, 2, 'commemorate', '/kəˈmeməreɪt/', 'v. 纪念，庆祝', 'The town built a statue to commemorate the heroes.', '小镇建了一座雕像来纪念英雄。', 48, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (197, 2, 'commence', '/kəˈmens/', 'v. 开始，着手', 'The ceremony will commence at nine sharp.', '典礼将于九点整开始。', 49, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (198, 2, 'complacent', '/kəmˈpleɪsnt/', 'adj. 自满的，得意的', 'Success can make a company dangerously complacent.', '成功会让公司陷入危险的自满。', 50, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (199, 2, 'concede', '/kənˈsiːd/', 'v. 承认；让步', 'He finally conceded that the plan had failed.', '他最终承认计划失败了。', 51, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (200, 2, 'conciliatory', '/kənˈsɪliətəri/', 'adj. 安抚的，调和的', 'She took a conciliatory tone during the negotiation.', '谈判中她采取了和解的口吻。', 52, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (201, 2, 'concise', '/kənˈsaɪs/', 'adj. 简明的，简练的', 'Keep your summary concise and to the point.', '把你的总结写得简明扼要。', 53, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (202, 2, 'condone', '/kənˈdəʊn/', 'v. 宽容，纵容', 'The school will not condone cheating of any kind.', '学校绝不纵容任何形式的作弊。', 54, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (203, 2, 'confide', '/kənˈfaɪd/', 'v. 吐露，信任', 'She confided her worries to her closest friend.', '她向最要好的朋友吐露了自己的烦恼。', 55, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (204, 2, 'congregate', '/ˈkɒŋɡrɪɡeɪt/', 'v. 聚集，集合', 'Tourists congregate around the old clock tower.', '游客聚集在古老的钟楼周围。', 56, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (205, 3, 'advise', '/ədˈvaɪz/', 'v. 建议，劝告', 'I advise you to sleep earlier before the exam.', '我建议你考试前早点睡。', 0, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (206, 3, 'alike', '/əˈlaɪk/', 'adj. 相像的 adv. 同样地', 'The twins look alike but behave differently.', '这对双胞胎长得很像，但行为不同。', 1, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (207, 3, 'alive', '/əˈlaɪv/', 'adj. 活着的，在世的', 'The old tree is still alive after the storm.', '风暴过后这棵老树仍然活着。', 2, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (208, 3, 'amaze', '/əˈmeɪz/', 'v. 使惊奇', 'Her memory never fails to amaze me.', '她的记忆力总让我惊叹。', 3, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (209, 3, 'ancient', '/ˈeɪnʃənt/', 'adj. 古代的，古老的', 'We visited an ancient temple on the mountain.', '我们参观了山上的一座古庙。', 4, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (210, 3, 'arrive', '/əˈraɪv/', 'v. 到达', 'The train arrived ten minutes late.', '火车晚点了十分钟。', 5, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (211, 3, 'attend', '/əˈtend/', 'v. 出席；参加', 'Over two hundred students attended the lecture.', '两百多名学生参加了讲座。', 6, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (212, 3, 'attitude', '/ˈætɪtjuːd/', 'n. 态度', 'A positive attitude makes hard work easier.', '积极的态度会让艰苦的工作变得轻松。', 7, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (213, 3, 'attract', '/əˈtrækt/', 'v. 吸引', 'The bright colours attract many visitors.', '鲜艳的颜色吸引了许多游客。', 8, '2026-10-19 21:14:46', 'active');
