INSERT INTO `words` VALUES (215, 3, 'belong', '/bɪˈlɒŋ/', 'v. 属于', 'This notebook belongs to my sister.', '这个笔记本是我妹妹的。', 10, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (216, 3, 'beneficial', '/ˌbenɪˈfɪʃl/', 'adj. 有益的', 'Reading daily is beneficial to your vocabulary.', '每天阅读对你的词汇量有益。', 11, '2026-10-19 21:14:46', 'active');
