INSERT INTO `words` VALUES (219, 3, 'calm', '/kɑːm/', 'adj. 冷静的 v. 使平静', 'Try to stay calm during the test.', '考试时尽量保持冷静。', 14, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (220, 3, 'cancel', '/ˈkænsl/', 'v. 取消', 'They cancelled the match because of heavy rain.', '由于大雨，他们取消了比赛。', 15, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (221, 3, 'care', '/keə(r)/', 'v./n. 关心，在乎', 'She cares deeply about her students.', '她非常关心自己的学生。', 16, '2026-10-19 21:14:46', 'active');
