INSERT INTO `words` VALUES (227, 3, 'comfortable', '/ˈkʌmftəbl/', 'adj. 舒适的', 'The new chair is much more comfortable.', '这把新椅子舒服多了。', 22, '2026-10-19 21:14:46', 'active');
