INSERT INTO `words` VALUES (230, 3, 'complete', '/kəmˈpliːt/', 'adj. 完整的 v. 完成', 'Please complete the form before Friday.', '请在周五之前填完表格。', 25, '2026-10-19 21:14:46', 'active');
