INSERT INTO `words` VALUES (255, 3, 'depend', '/dɪˈpend/', 'v. 依靠；取决于', 'Whether we go depends on the weather.', '我们去不去取决于天气。', 50, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (256, 4, 'aesthetic', '/iːsˈθetɪk/', 'adj. 美学的，审美的 n. 美感', 'The building is admired for its aesthetic value.', '这座建筑因其美学价值而受到赞赏。', 0, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (257, 4, 'aggregate', '/ˈæɡrɪɡət/', 'n. 总数，合计 adj. 总计的', 'The aggregate cost of the project is still unknown.', '该项目的总成本仍不清楚。', 1, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (258, 4, 'alienate', '/ˈeɪliəneɪt/', 'v. 使疏远，离间', 'His harsh tone alienated several close friends.', '他尖刻的语气疏远了几位密友。', 2, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (259, 4, 'allege', '/əˈledʒ/', 'v. 声称，断言', 'The report alleges that safety rules were ignored.', '报告声称安全规定被无视了。', 3, '2026-10-19 21:14:46', 'active');
