INSERT INTO `words` VALUES (262, 4, 'anonymous', '/əˈnɒnɪməs/', 'adj. 匿名的', 'The letter came from an anonymous sender.', '这封信来自一位匿名寄信人。', 6, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (263, 4, 'authentic', '/ɔːˈθentɪk/', 'adj. 真正的，可信的', 'The museum confirmed the painting was authentic.', '博物馆确认这幅画是真迹。', 7, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (264, 4, 'autonomy', '/ɔːˈtɒnəmi/', 'n. 自主权，自治', 'Each department was given greater autonomy.', '每个部门都获得了更大的自主权。', 8, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (265, 4, 'banal', '/bəˈnɑːl/', 'adj. 平庸的，陈腐的', 'The film was full of banal dialogue.', '这部电影充满了平庸的对白。', 9, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (266, 4, 'bureaucracy', '/bjʊəˈrɒkrəsi/', 'n. 官僚机构，繁文缛节', 'The application was delayed by endless bureaucracy.', '申请被无休止的官僚程序拖延了。', 10, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (267, 4, 'catalyst', '/ˈkætəlɪst/', 'n. 催化剂；促进因素', 'The crisis became a catalyst for reform.', '这场危机成了改革的催化剂。', 11, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (268, 4, 'comprehensive', '/ˌkɒmprɪˈhensɪv/', 'adj. 综合的，全面的', 'The school offers a comprehensive training programme.', '学校提供全面的培训项目。', 12, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (269, 4, 'compromise', '/ˈkɒmprəmaɪz/', 'n./v. 妥协，折中', 'Both sides finally reached a compromise.', '双方最终达成了妥协。', 13, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (270, 4, 'conceive', '/kənˈsiːv/', 'v. 构思；怀孕', 'It is hard to conceive of life without the internet.', '很难想象没有互联网的生活。', 14, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (271, 4, 'concurrent', '/kənˈkʌrənt/', 'adj. 同时发生的', 'The university runs two concurrent research projects.', '这所大学同时开展两个研究项目。', 15, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (272, 4, 'conducive', '/kənˈdjuːsɪv/', 'adj. 有助的，有益的', 'A quiet room is conducive to deep study.', '安静的房间有助于深入学习。', 16, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (273, 4, 'confine', '/kənˈfaɪn/', 'v. 限制，禁闭', 'Do not confine yourself to the textbook.', '不要把自己局限在课本之内。', 17, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (274, 4, 'conform', '/kənˈfɔːm/', 'v. 遵守，符合', 'All products must conform to national standards.', '所有产品都必须符合国家标准。', 18, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (275, 4, 'conspicuous', '/kənˈspɪkjuəs/', 'adj. 显眼的，显著的', 'Her absence was conspicuous at the meeting.', '她的缺席在会上十分显眼。', 19, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (276, 4, 'constrain', '/kənˈstreɪn/', 'v. 限制，约束', 'Limited funds constrained the scope of the research.', '资金有限限制了研究的范围。', 20, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (277, 4, 'contemplate', '/ˈkɒntəmpleɪt/', 'v. 沉思，考虑', 'She contemplated changing careers entirely.', '她认真考虑过彻底转换职业。', 21, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (278, 4, 'contemporary', '/kənˈtemprəri/', 'adj. 当代的 n. 同代人', 'The gallery focuses on contemporary art.', '这家画廊专注于当代艺术。', 22, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (279, 4, 'contradict', '/ˌkɒntrəˈdɪkt/', 'v. 反驳；与…相矛盾', 'The two accounts of the event contradict each other.', '关于该事件的两种说法相互矛盾。', 23, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (280, 4, 'controversial', '/ˌkɒntrəˈvɜːʃl/', 'adj. 有争议的', 'The new regulation remains highly controversial.', '这项新规定仍极具争议。', 24, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (281, 4, 'conventional', '/kənˈvenʃənl/', 'adj. 传统的，常规的', 'She rejected the conventional approach to teaching.', '她摒弃了传统的教学方法。', 25, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (282, 4, 'correlate', '/ˈkɒrəleɪt/', 'v. 相关联', 'Sleep quality correlates strongly with concentration.', '睡眠质量与专注力高度相关。', 26, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (283, 4, 'counterpart', '/ˈkaʊntəpɑːt/', 'n. 对应的人或物', 'She met her counterpart in the Berlin office.', '她会见了柏林办公室的对口同事。', 27, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (284, 4, 'credible', '/ˈkredəbl/', 'adj. 可信的，可靠的', 'The theory lacks credible supporting evidence.', '该理论缺乏可信的佐证。', 28, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (285, 4, 'culminate', '/ˈkʌlmɪneɪt/', 'v. 达到顶点，告终', 'Years of effort culminated in a published book.', '多年的努力最终凝聚成一本出版的书。', 29, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (286, 4, 'cumulative', '/ˈkjuːmjələtɪv/', 'adj. 累积的', 'The cumulative effect of stress was serious.', '压力的累积效应相当严重。', 30, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (287, 4, 'curb', '/kɜːb/', 'v./n. 抑制，约束', 'The city took steps to curb air pollution.', '该市采取措施抑制空气污染。', 31, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (288, 4, 'decree', '/dɪˈkriː/', 'n. 法令 v. 颁布', 'The king issued a decree banning the trade.', '国王颁布法令禁止这项贸易。', 32, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (289, 4, 'dedicate', '/ˈdedɪkeɪt/', 'v. 致力于，奉献', 'She dedicated her life to medical research.', '她把一生奉献给了医学研究。', 33, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (290, 4, 'deliberate', '/dɪˈlɪbərət/', 'adj. 故意的；从容的', 'The delay was a deliberate attempt to confuse us.', '这次拖延是故意让我们困惑。', 34, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (291, 4, 'demonstrate', '/ˈdemənstreɪt/', 'v. 证明；示范', 'The experiment demonstrates how the drug works.', '该实验展示了这种药物的作用机制。', 35, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (292, 4, 'denounce', '/dɪˈnaʊns/', 'v. 谴责，告发', 'Many leaders denounced the act of violence.', '许多领导人谴责了这暴力行为。', 36, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (293, 4, 'deteriorate', '/dɪˈtɪəriəreɪt/', 'v. 恶化，变坏', 'His health deteriorated rapidly after the accident.', '事故后他的健康状况迅速恶化。', 37, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (294, 4, 'devise', '/dɪˈvaɪz/', 'v. 设计，发明', 'The engineers devised a safer locking system.', '工程师们设计出一套更安全的锁止系统。', 38, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (295, 4, 'devote', '/dɪˈvəʊt/', 'v. 投入，奉献', 'He devoted every evening to learning French.', '他把每个晚上都用来学法语。', 39, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (296, 4, 'diffuse', '/dɪˈfjuːz/', 'v. 扩散；传播 adj. 弥漫的', 'The technology quickly diffused across the industry.', '这项技术迅速在整个行业扩散开来。', 40, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (297, 4, 'dilemma', '/dɪˈlemə/', 'n. 困境，两难', 'She faced a dilemma between work and study.', '她面临工作与学习的两难选择。', 41, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (298, 4, 'diminish', '/dɪˈmɪnɪʃ/', 'v. 减少，缩小', 'The pain gradually diminished over several days.', '疼痛在几天里逐渐减轻。', 42, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (299, 4, 'discard', '/dɪsˈkɑːd/', 'v. 丢弃，抛弃', 'We should discard outdated methods completely.', '我们应当彻底抛弃过时的方法。', 43, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (300, 4, 'discern', '/dɪˈsɜːn/', 'v. 辨别，看出', 'It was hard to discern the truth from the rumours.', '很难从谣言中辨别真相。', 44, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (301, 4, 'disperse', '/dɪˈspɜːs/', 'v. 驱散；分散', 'The police dispersed the crowd peacefully.', '警方和平地疏散了人群。', 45, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (302, 4, 'distinct', '/dɪˈstɪŋkt/', 'adj. 明显的；不同的', 'The two proposals offer distinct advantages.', '这两个方案各有明显的优势。', 46, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (303, 4, 'distort', '/dɪˈstɔːt/', 'v. 歪曲，扭曲', 'The media often distorts the full story.', '媒体常常歪曲事件的全貌。', 47, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (304, 4, 'divert', '/daɪˈvɜːt/', 'v. 使转向，转移', 'They diverted the river to protect the town.', '他们改变河道以保护小镇。', 48, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (305, 4, 'doctrine', '/ˈdɒktrɪn/', 'n. 学说，教义', 'This doctrine influenced generations of scholars.', '这一学说影响了一代又一代学者。', 49, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (306, 4, 'domain', '/dəˈmeɪn/', 'n. 领域，范围', 'Linguistics is a domain she knows very well.', '语言学是她非常熟悉的领域。', 50, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (307, 4, 'domestic', '/dəˈmestɪk/', 'adj. 国内的；家庭的', 'Domestic demand grew faster than exports.', '国内需求的增长快于出口。', 51, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (308, 4, 'drastic', '/ˈdræstɪk/', 'adj. 激烈的，猛烈的', 'Drastic measures were needed to cut costs.', '需要采取激烈措施来削减成本。', 52, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (309, 4, 'durable', '/ˈdjʊərəbl/', 'adj. 耐久的，持久的', 'These materials are cheap and durable.', '这些材料既便宜又耐用。', 53, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (310, 4, 'elaborate', '/ɪˈlæbərət/', 'adj. 精心制作的 v. 详细阐述', 'Could you elaborate on that last point?', '你能详细说明一下最后那一点吗？', 54, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (311, 4, 'eliminate', '/ɪˈlɪmɪneɪt/', 'v. 消除，淘汰', 'The new filter eliminates most impurities.', '新滤芯能消除大部分杂质。', 55, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (312, 4, 'embody', '/ɪmˈbɒdi/', 'v. 体现，使具体化', 'The statue embodies the spirit of the city.', '这座雕像体现了这座城市的精神。', 56, '2026-10-19 21:14:46', 'active');
INSERT INTO `words` VALUES (313, 4, 'empirical', '/ɪmˈpɪrɪkl/', 'adj. 经验主义的，实证的', 'The claim has no empirical support so far.', '这一说法至今没有实证支持。', 57, '2026-10-19 21:14:46', 'active');
